+ars.hull <- function(x, hv, dhv, L, U, tol.slope = 1e-4) {
+  k <- length(x)
+  if (any(!is.finite(hv))) {
+    stop("ars: density must be positive and finite at all abscissae")
+  }
+  if (any(!is.finite(dhv))) {
+    stop("ars: could not compute finite derivative at all abscissae (density may be non-log-concave or non-differentiable there)")
+  }
+  if (k >= 2L && any(diff(dhv) > tol.slope)) {
+    stop("ars: non-log-concave density detected (derivatives are not decreasing)")
+  }
+  z <- numeric(k + 1L)
+  z[1L] <- L
+  z[k + 1L] <- U
+  if (k >= 2L) {
+    for (j in 1:(k - 1L)) {
+      denom <- dhv[j] - dhv[j + 1L]
+      if (abs(denom) < 1e-12) {
+        z[j + 1L] <- (x[j] + x[j + 1L]) / 2
+      } else {
+        z[j + 1L] <- (hv[j + 1L] - hv[j] - x[j + 1L] * dhv[j + 1L] + x[j] * dhv[j]) / denom
+      }
+    }
+    if (any(!is.finite(z[2L:k]))) {
+      stop("ars: non-log-concave density detected (non-finite hull intersection)")
+    }
+    if (any(diff(z) <= 0)) {
+      stop("ars: non-log-concave density detected (hull intersections out of order)")
+    }
+    for (j in 1:k) {
+      if (!(z[j] <= x[j] + 1e-8 && x[j] <= z[j + 1L] + 1e-8)) {
+        stop("ars: non-log-concave density detected (abscissa outside its hull interval)")
+      }
+    }
+  }
+  # Envelope must be proper on unbounded domains.
+  if (!is.finite(L) && dhv[1L] <= 0) {
+    stop("ars: non-log-concave density detected or starting points do not bracket the mode (left envelope is improper)")
+  }
+  if (!is.finite(U) && dhv[k] >= 0) {
+    stop("ars: non-log-concave density detected or starting points do not bracket the mode (right envelope is improper)")
+  }
+  logw <- numeric(k)
+  for (j in 1:k) {
+    l <- z[j]
+    r <- z[j + 1L]
+    b <- dhv[j]
+    if (!(r > l)) {
+      logw[j] <- -Inf
+      next
+    }
+    if (abs(b) < 1e-8) {
+      if (!is.finite(l) || !is.finite(r)) {
+        stop("ars: non-log-concave density detected or starting points do not bracket the mode (flat improper envelope)")
+      }
+      logw[j] <- hv[j] + log(r - l)
+    } else if (!is.finite(l)) {
+      logw[j] <- hv[j] + b * (r - x[j]) - log(b)
+    } else if (!is.finite(r)) {
+      logw[j] <- hv[j] + b * (l - x[j]) - log(-b)
+    } else {
+      a <- b * (l - x[j])
+      bb <- b * (r - x[j])
+      m <- max(a, bb)
+      logw[j] <- hv[j] - log(abs(b)) + m + log1p(-exp(min(a, bb) - m))
+    }
+  }
+  if (all(!is.finite(logw))) {
+    stop("ars: envelope has no finite mass (check domain and starting abscissae)")
+  }
+  m <- max(logw[is.finite(logw)])
+  w <- exp(logw - m)
+  w[!is.finite(w)] <- 0
+  probs <- w / sum(w)
+  list(z = z, probs = probs, logw = logw)
+}
+
+ars.upper <- function(xstar, x, hv, dhv, z) {
+  k <- length(x)
+  for (j in 1:k) {
+    if (xstar >= z[j] && xstar <= z[j + 1L]) {
+      return(hv[j] + (xstar - x[j]) * dhv[j])
+    }
+  }
+  stop("ars: candidate outside envelope support (possible non-log-concavity)")
+}
+
+ars.lower <- function(xstar, x, hv) {
+  k <- length(x)
+  if (xstar < x[1L] || xstar > x[k]) return(-Inf)
+  for (j in 1:(k - 1L)) {
+    if (xstar >= x[j] && xstar <= x[j + 1L]) {
+      if (x[j + 1L] == x[j]) return(hv[j])
+      return(((x[j + 1L] - xstar) * hv[j] + (xstar - x[j]) * hv[j + 1L]) / (x[j + 1L] - x[j]))
+    }
+  }
+  # xstar coincides numerically with an abscissa.
+  hv[which.min(abs(x - xstar))]
+}
+
+ars.sample.envelope <- function(x, hv, dhv, z, probs) {
+  k <- length(x)
+  j <- sample.int(k, 1L, prob = probs)
+  l <- z[j]
+  r <- z[j + 1L]
+  b <- dhv[j]
+  u <- stats::runif(1)
+  if (abs(b) < 1e-8) {
+    return(l + u * (r - l))
+  }
+  if (!is.finite(l)) {
+    return(r + log(u) / b)
+  }
+  if (!is.finite(r)) {
+    return(l + log1p(-u) / b)
+  }
+  d <- b * (r - l)
+  if (b > 0) {
+    return(r + log(u + (1 - u) * exp(-d)) / b)
+  } else {
+    return(l + log((1 - u) + u * exp(d)) / b)
+  }
