+  iters <- 0L
+  max.iters <- 100L * n + 10000L
+  while (n.accept < n) {
+    iters <- iters + 1L
+    if (iters > max.iters) {
+      stop("ars: exceeded maximum iterations (density may be non-log-concave or envelope is inefficient)")
+    }
